// Resolves the farmer's own free-text state/district onto AGMARKNET's exact
// spellings. The farmer's record is never rewritten — this only decides what
// to ask the API for.
//
// DISTRICT_MAP below is derived from AGMARKNET's own district values
// (resource 9ef84268-d588-465a-a308-a864a43d0070), captured from a full
// snapshot: 21 states, 284 districts. It is not a hand-written guess list.
// It reflects the districts that reported arrivals in that snapshot, so it
// needs refreshing when AGMARKNET's district list changes — see
// services/n8n/README.md.
//
// Matching rule, validated against all 284 districts with zero collisions:
// lowercase → letters only → drop "h" (aspirates) → drop vowels → collapse
// doubled consonants. Indic transliteration varies almost entirely in vowels
// and aspirates, so the consonant skeleton is the stable part. "thiruvallur"
// and "Thiruvellore" both reduce to "trvlr".
//
// This is exact resolution of one district under a different spelling, not
// fuzzy matching: a skeleton matching zero districts — or more than one —
// resolves to nothing and the caller gets "unavailable". Matching is scoped
// to the state, so the same text cannot resolve into a different state.

const DISTRICT_MAP = {
  "Andhra Pradesh": ["Alluri Sitharama Raju","Anakapally","Ananthapuramu","Annamayya","Bapatla","Dr.B.R.A.Konaseema","East Godavari","Eluru","Kakinada","Markapuram","NTR","Nandyal","Palnadu","Prakasam","SPSR Nellore","Srikakulam","Visakhapatnam","YSR Kadapa"],
  "Assam": ["Tinsukia"],
  "Bihar": ["Begusarai","Bhagalpur","Buxar","Chhapra","Madhubani","Sheikhpura"],
  "Chattisgarh": ["Kanker","Kondagaon","Manendragarh Chirmiri Bhartpur","Raipur","Sarangarh Bilaigarh","Surajpur"],
  "Gujarat": ["Ahmedabad","Amreli","Narmada","Rajkot"],
  "Haryana": ["Faridabad","Gurgaon","Hissar","Jind","Kaithal","Karnal","Kurukshetra","Mahendragarh-Narnaul","Palwal","Panipat","Rewari","Sirsa","Sonipat","Yamuna Nagar"],
  "Himachal Pradesh": ["Kullu","Mandi","Solan"],
  "Karnataka": ["Bengaluru South","Bidar","Chikkamagaluru","Haveri","Koppal","Vijayanagara"],
  "Keralam": ["Alappuzha","Ernakulam","Idukki","Kollam","Kottayam","Kozhikode(Calicut)","Malappuram","Palakad","Pathanamthitta","Thirssur","Thiruvananthapuram"],
  "Madhya Pradesh": ["Agar Malwa","Alirajpur","Ashoknagar","Badwani","Balaghat","Betul","Bhind","Bhopal","Chhindwara","Dewas","Dhar","Dindori","Guna","Gwalior","Harda","Indore","Katni","Khargone","Mandla","Mandsaur","Morena","Narmadapuram","Narsinghpur","Raisen","Rajgarh","Ratlam","Rewa","Sagar","Satna","Sehore","Seoni","Sidhi","Tikamgarh","Ujjain"],
  "Maharashtra": ["Ahilyanagar","Amarawati","Chattrapati Sambhajinagar","Dharashiv","Gadchiroli","Jalgaon","Kolhapur","Latur","Nagpur","Parbhani","Pune","Raigad","Sangli","Satara","Solapur"],
  "NCT of Delhi": ["Delhi"],
  "Odisha": ["Angul","Balasore","Bargarh","Bhadrak","Bolangir","Dhenkanal","Ganjam","Jharsuguda","Kalahandi","Keonjhar","Khurda","Mayurbhanja","Puri","Sundergarh"],
  "Punjab": ["Amritsar","Ferozpur","Gurdaspur","Hoshiarpur","Jalandhar","Kapurthala","Ludhiana","Patiala","Sangrur","Tarntaran"],
  "Rajasthan": ["Bharatpur","Hanumangarh","Jalore","Jhunjhunu","Tonk"],
  "Tamil Nadu": ["Ariyalur","Chengalpattu","Coimbatore","Cuddalore","Dharmapuri","Dindigul","Erode","Kallakuruchi","Kancheepuram","Karur","Krishnagiri","Madurai","Nagapattinam","Nagercoil (Kannyiakumari)","Namakkal","Perambalur","Pudukkottai","Ramanathapuram","Ranipet","Salem","Sivaganga","Tenkasi","Thanjavur","The Nilgiris","Theni","Thiruchirappalli","Thirunelveli","Thirupathur","Thirupur","Thiruvannamalai","Thiruvarur","Thiruvellore","Tuticorin","Vellore","Villupuram","Virudhunagar"],
  "Telangana": ["Bhadradri Kothagudem","Hanumakonda","Hyderabad","Jogulamba Gadwal","Karimnagar","Khammam","Medchal Malkajgiri","Nagarkurnool","Ranga Reddy","Siddipet","Wanaparthy","Warangal"],
  "Tripura": ["Dhalai","Khowai","North Tripura","Sepahijala","South Tripura"],
  "Uttar Pradesh": ["Agra","Aligarh","Ambedkarnagar","Amethi","Amroha","Auraiya","Ayodhya","Azamgarh","Badaun","Baghpat","Bahraich","Ballia","Balrampur","Banda","Barabanki","Bareilly","Basti","Bijnor","Bulandshahar","Chandauli","Chitrakut","Deoria","Etah","Etawah","Farukhabad","Fatehpur","Firozabad","Gautam Budh Nagar","Ghaziabad","Ghazipur","Gonda","Gorakhpur","Hamirpur","Hardoi","Hathras","Jalaun (Orai)","Jaunpur","Jhansi","Kannuj","Kanpur","Kanpur Dehat","Kasganj","Kaushambi","Khiri (Lakhimpur)","Lakhimpur","Lalitpur","Lucknow","Maharajganj","Mahoba","Mainpuri","Mathura","Meerut","Mirzapur","Muzaffarnagar","Pillibhit","Pratapgarh","Prayagraj","Raebarelli","Rampur","Saharanpur","Sambhal","Sant Kabir Nagar","Shahjahanpur","Shamli","Shravasti","Siddharth Nagar","Sitapur","Sonbhadra","Unnao","Varanasi"],
  "Uttarakhand": ["Dehradoon","Haridwar","Nanital","Udhamsinghnagar"],
  "West Bengal": ["Bankura","Birbhum","Darjeeling","Hooghly","Kolkata","North 24 Parganas","Purba Bardhaman","Puruliya","Sounth 24 Parganas"]
};

// Names that are not spelling variants at all — a nickname, an article, a
// suffix, an administrative prefix. Each target is an AGMARKNET value.
const STATE_ALIASES = {
  kerala: "Keralam",
  orissa: "Odisha",
  chhattisgarh: "Chattisgarh",
  delhi: "NCT of Delhi",
  newdelhi: "NCT of Delhi",
  uttaranchal: "Uttarakhand"
};

const DISTRICT_ALIASES = {
  "Tamil Nadu": {
    trichy: "Thiruchirappalli",
    tiruchirapalli: "Thiruchirappalli",
    nilgiris: "The Nilgiris",
    ooty: "The Nilgiris",
    kanyakumari: "Nagercoil (Kannyiakumari)"
  }
};

function skeleton(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z]/g, "")
    .replace(/h/g, "")
    .replace(/[aeiou]/g, "")
    .replace(/(.)\1+/g, "$1");
}

function plain(value) {
  return String(value || "").toLowerCase().replace(/[^a-z]/g, "");
}

/** The single matching canonical name, or null when zero or more than one match. */
function resolveOne(input, candidates, aliases) {
  const raw = plain(input);
  if (!raw) return null;
  if (aliases && aliases[raw]) return aliases[raw];
  const exact = candidates.find((c) => plain(c) === raw);
  if (exact) return exact;
  const key = skeleton(input);
  if (!key) return null;
  const hits = candidates.filter((c) => skeleton(c) === key);
  // More than one hit is ambiguous, and guessing between real districts is
  // exactly what must not happen here.
  return hits.length === 1 ? hits[0] : null;
}

const input = $input.first()?.json ?? {};
const askedState = String(input.state ?? "").trim();
const askedDistrict = String(input.district ?? "").trim();
const commodity = String(input.commodity ?? "").trim();

const state = resolveOne(askedState, Object.keys(DISTRICT_MAP), STATE_ALIASES);
if (!state) {
  return [{ json: { resolved: false, reasonKey: "state", askedState, askedDistrict, commodity } }];
}

const district = resolveOne(askedDistrict, DISTRICT_MAP[state], DISTRICT_ALIASES[state]);
if (!district) {
  return [{ json: { resolved: false, reasonKey: "district", askedState, askedDistrict, state, commodity } }];
}

if (!commodity) {
  return [{ json: { resolved: false, reasonKey: "commodity", askedState, askedDistrict, state, district, commodity: "" } }];
}

return [{ json: { resolved: true, state, district, commodity, askedState, askedDistrict } }];

// The farmer's state/district could not be matched to an AGMARKNET district,
// so no query was made. The message names exactly what was searched for, so
// the farmer can see the mismatch and correct their farm record — guessing a
// nearby district would be worse than saying nothing.

const r = $input.first()?.json ?? {};
const asked = r.askedDistrict || "(not set)";
const state = r.state || r.askedState || "(not set)";

let reason;
switch (r.reasonKey) {
  case "state":
    reason = `No market data source matches the state "${r.askedState || "(not set)"}" on this farm. Check the state on the farm record.`;
    break;
  case "commodity":
    reason = "No crop was selected, so there is nothing to look up.";
    break;
  default:
    reason = `No market district matching "${asked}" was found in ${state}. Check the district on the farm record.`;
}

console.log("Market lookup unresolved:", JSON.stringify({ reasonKey: r.reasonKey, askedState: r.askedState, askedDistrict: r.askedDistrict }));

return [{ json: { status: "unavailable", reason } }];

// AGMARKNET failed or was unreachable. The farmer gets a plain message; the
// technical detail goes to the n8n execution log so failures stay
// diagnosable without exposing the provider or HTTP internals in the UI.

const statusCode = $json.statusCode ?? "unknown";
let body = $json.body ?? {};
if (typeof body === "string") {
  try { body = JSON.parse(body); } catch { body = { error: body }; }
}
const detail = body?.error ?? body?.message ?? $json.error?.message ?? "No error message returned.";
console.log("AGMARKNET failure detail:", statusCode, detail);

return [
  {
    json: {
      status: "unavailable",
      reason: "The market price service is currently unavailable. Please try again."
    }
  }
];

// Maps the AGMARKNET response into the MarketSnapshot contract
// (packages/shared-types). Every price passes through exactly as the source
// reported it; a field the source omitted becomes null, never 0 — a zero
// rupee price would read as "free", which is worse than "not reported".
//
// Verified response shape (resource 9ef84268-d588-465a-a308-a864a43d0070):
//   { state, district, market, commodity, variety, grade,
//     arrival_date: "DD/MM/YYYY", min_price, max_price, modal_price }
// Prices are numbers in rupees per quintal. arrival_date is a DD/MM/YYYY
// string, not ISO, so it is parsed explicitly rather than handed to Date().
//
// This resource is a DAILY SNAPSHOT: every row in it carries the same
// arrival date. There is no history to page through, which is also why the
// UI shows a current snapshot and no trend charts.

const SOURCE = "agmarknet-data.gov.in";

const resolved = $('Resolve Location').first().json;

const input = $input.first()?.json ?? {};
let body = input.body ?? input;
if (typeof body === "string") {
  try { body = JSON.parse(body); } catch { body = {}; }
}

const records = Array.isArray(body.records) ? body.records : [];

// A 200 with an empty records array is how this API reports "nothing
// matched" — status is still "ok", so the count has to be checked explicitly.
if (records.length === 0) {
  return [
    {
      json: {
        status: "unavailable",
        reason: `No market data was reported today for ${resolved.commodity} in ${resolved.district}.`
      }
    }
  ];
}

const num = (v) => {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  // The API has been seen to return numbers; tolerate numeric strings
  // without inventing a value for anything genuinely absent.
  if (typeof v === "string" && v.trim() !== "" && Number.isFinite(Number(v))) return Number(v);
  return null;
};

const text = (v) => (typeof v === "string" && v.trim() !== "" ? v.trim() : null);

/** "DD/MM/YYYY" -> "YYYY-MM-DD", or null if it isn't that shape. */
const toIsoDate = (v) => {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(v || "").trim());
  if (!m) return null;
  const [, dd, mm, yyyy] = m;
  const day = Number(dd), month = Number(mm);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  return `${yyyy}-${mm}-${dd}`;
};

const quotes = [];
for (const r of records) {
  if (!r || typeof r !== "object") continue;
  const market = text(r.market);
  // A quote with no market name cannot be shown or distinguished from the
  // others, so it is dropped rather than rendered as a blank row.
  if (!market) continue;
  quotes.push({
    market,
    variety: text(r.variety),
    grade: text(r.grade),
    minPrice: num(r.min_price),
    maxPrice: num(r.max_price),
    modalPrice: num(r.modal_price),
    reportedOn: toIsoDate(r.arrival_date)
  });
}

if (quotes.length === 0) {
  return [
    {
      json: {
        status: "unavailable",
        reason: `No market data was reported today for ${resolved.commodity} in ${resolved.district}.`
      }
    }
  ];
}

// Newest first. Rows without a parseable date sort last rather than being
// dropped — the price is still real, only its date is unreadable.
quotes.sort((a, b) => {
  if (a.reportedOn === b.reportedOn) return 0;
  if (a.reportedOn === null) return 1;
  if (b.reportedOn === null) return -1;
  return a.reportedOn < b.reportedOn ? 1 : -1;
});

const dates = quotes.map((q) => q.reportedOn).filter((d) => d !== null);
const latestReportedOn = dates.length > 0 ? dates[0] : null;

return [
  {
    json: {
      status: "ok",
      asOf: new Date().toISOString(),
      source: SOURCE,
      data: {
        commodity: resolved.commodity,
        state: resolved.state,
        district: resolved.district,
        latestReportedOn,
        priceUnit: "INR_PER_QUINTAL",
        quotes
      }
    }
  }
];
